CREATE TABLE IF NOT EXISTS "bonus_grant" ("id" text PRIMARY KEY NOT NULL,"organizationId" text NOT NULL REFERENCES "organization"("id") ON DELETE CASCADE,"rewardAccountId" text NOT NULL REFERENCES "customer_reward_account"("id") ON DELETE CASCADE,"customerId" text NOT NULL REFERENCES "customer"("id") ON DELETE CASCADE,"promotionRuleId" text,"sourceSaleId" text,"originalAmount" numeric(12,2) NOT NULL,"remainingAmount" numeric(12,2) NOT NULL,"issuedAt" timestamp NOT NULL,"expiresAt" timestamp,"status" text NOT NULL DEFAULT 'ACTIVE',"idempotencyKey" text NOT NULL,"createdAt" timestamp NOT NULL DEFAULT now(),"updatedAt" timestamp NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "bonus_grant_org_idem_unique" ON "bonus_grant" ("organizationId","idempotencyKey");
CREATE INDEX IF NOT EXISTS "bonus_grant_account_expiry_idx" ON "bonus_grant" ("rewardAccountId","status","expiresAt");
